import { NextRequest, NextResponse } from "next/server";

// 访问口令:在 .env.local 配 APP_PASSWORD 即开启门禁;不配则放行(本地开发零配置)。
// 前端把口令放在请求头 x-app-password,服务端逐请求校验。
export const AUTH_HEADER = "x-app-password";

export function authEnabled(): boolean {
  return Boolean(process.env.APP_PASSWORD);
}

// 通过返回 null,失败返回 401 响应
export function checkAuth(req: NextRequest): NextResponse | null {
  const expected = process.env.APP_PASSWORD;
  if (!expected) return null;
  const got = req.headers.get(AUTH_HEADER);
  if (got === expected) return null;
  return NextResponse.json({ error: "未授权:请提供正确的访问口令" }, { status: 401 });
}

