"use client";

// 访问口令存在浏览器本地;请求时放进 x-app-password 头。
// 仅当服务端配置了 APP_PASSWORD 才会真正校验;未配置时本 helper 发空头也能正常工作。
const KEY = "app-password";
const HEADER = "x-app-password";

export function getPassword(): string {
  if (typeof window === "undefined") return "";
  return window.localStorage.getItem(KEY) || "";
}

export function setPassword(pw: string): void {
  if (typeof window === "undefined") return;
  if (pw) window.localStorage.setItem(KEY, pw);
  else window.localStorage.removeItem(KEY);
}

export function authHeaders(): Record<string, string> {
  const pw = getPassword();
  return pw ? { [HEADER]: pw } : {};
}

// 自动带口令;若 401 则弹窗询问一次、存下并重试。
export async function authFetch(
  input: string,
  init: RequestInit = {}
): Promise<Response> {
  const withHeader = (): RequestInit => ({
    ...init,
    headers: { ...(init.headers || {}), ...authHeaders() },
  });

  let res = await fetch(input, withHeader());
  if (res.status === 401 && typeof window !== "undefined") {
    const pw = window.prompt("请输入访问口令");
    if (pw) {
      setPassword(pw);
      res = await fetch(input, withHeader());
    }
  }
  return res;
}

