import { promises as fs } from "node:fs";
import path from "node:path";
import type { BrandFacts, StyleEntry } from "@/lib/types";

// 数据层单一出入口:运行时读写 data/*.json,而非构建期静态 import,
// 这样后台编辑保存后能即时生效。写入做 schema 校验 + 原子写 + 备份。
//
// userId 参数为未来"每人账号 + 各自风格库"预留;短期单实例全局共享,忽略该参数。

const DATA_DIR = path.join(process.cwd(), "data");
const STYLE_PATH = path.join(DATA_DIR, "style-palette.json");
const BRAND_PATH = path.join(DATA_DIR, "brand-facts.json");
const BACKUP_DIR = path.join(DATA_DIR, "backups");

async function readJson<T>(filePath: string): Promise<T> {
  const raw = await fs.readFile(filePath, "utf-8");
  return JSON.parse(raw) as T;
}

// 先备份旧版,再原子写(临时文件 + rename),避免写一半损坏。
async function backupAndWrite(
  filePath: string,
  name: string,
  data: unknown
): Promise<void> {
  try {
    const current = await fs.readFile(filePath, "utf-8");
    await fs.mkdir(BACKUP_DIR, { recursive: true });
    const ts = new Date().toISOString().replace(/[:.]/g, "-");
    await fs.writeFile(path.join(BACKUP_DIR, `${name}.${ts}.json`), current, "utf-8");
  } catch {
    // 旧文件不存在或不可读:跳过备份,继续写入
  }
  const tmp = `${filePath}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(data, null, 2) + "\n", "utf-8");
  await fs.rename(tmp, filePath);
}

// ---- 风格库 ----

export async function getStylePalette(_userId?: string): Promise<StyleEntry[]> {
  return readJson<StyleEntry[]>(STYLE_PATH);
}

export function validateStylePalette(data: unknown): {
  ok: boolean;
  error?: string;
  value?: StyleEntry[];
} {
  if (!Array.isArray(data)) return { ok: false, error: "风格库必须是数组" };
  const ids = new Set<string>();
  const value: StyleEntry[] = [];
  for (let i = 0; i < data.length; i++) {
    const e = data[i] as Record<string, unknown>;
    if (!e || typeof e !== "object")
      return { ok: false, error: `第 ${i + 1} 项不是对象` };
    const { id, name, essence, group } = e;
    if (typeof id !== "string" || !id.trim())
      return { ok: false, error: `第 ${i + 1} 项缺少 id` };
    if (ids.has(id)) return { ok: false, error: `id 重复:${id}` };
    ids.add(id);
    if (typeof name !== "string" || !name.trim())
      return { ok: false, error: `${id} 缺少 name` };
    if (typeof essence !== "string" || !essence.trim())
      return { ok: false, error: `${id} 缺少 essence` };
    if (typeof group !== "string" || !group.trim())
      return { ok: false, error: `${id} 缺少 group` };
    value.push({
      id,
      name,
      essence,
      group,
      isDefault: e.isDefault === true,
    });
  }
  return { ok: true, value };
}

export async function saveStylePalette(
  palette: StyleEntry[],
  _userId?: string
): Promise<void> {
  await backupAndWrite(STYLE_PATH, "style-palette", palette);
}

// ---- 品牌事实 ----

export async function getBrandFacts(_userId?: string): Promise<BrandFacts> {
  return readJson<BrandFacts>(BRAND_PATH);
}

function isStringArray(x: unknown): x is string[] {
  return Array.isArray(x) && x.every((s) => typeof s === "string");
}

export function validateBrandFacts(data: unknown): {
  ok: boolean;
  error?: string;
  value?: BrandFacts;
} {
  if (!data || typeof data !== "object")
    return { ok: false, error: "品牌事实必须是对象" };
  const b = data as Record<string, unknown>;
  if (typeof b.brand !== "string" || !b.brand.trim())
    return { ok: false, error: "缺少 brand" };

  const positioning = b.positioning as Record<string, unknown> | undefined;
  if (!positioning || typeof positioning !== "object")
    return { ok: false, error: "缺少 positioning" };

  const toneCard = b.toneCard as Record<string, unknown> | undefined;
  if (!toneCard || typeof toneCard !== "object")
    return { ok: false, error: "缺少 toneCard" };
  if (!isStringArray(toneCard.do) || !isStringArray(toneCard.dont))
    return { ok: false, error: "toneCard.do / dont 必须是字符串数组" };

  const compliance = b.compliance as Record<string, unknown> | undefined;
  if (!compliance || typeof compliance !== "object")
    return { ok: false, error: "缺少 compliance" };
  // guards 依赖 bannedPhrases,这里强约束它必须是字符串数组
  if (!isStringArray(compliance.bannedPhrases))
    return { ok: false, error: "compliance.bannedPhrases 必须是字符串数组" };

  if (!Array.isArray(b.products))
    return { ok: false, error: "products 必须是数组" };
  if (!isStringArray(b.proofPoints))
    return { ok: false, error: "proofPoints 必须是字符串数组" };
  if (!Array.isArray(b.terminology))
    return { ok: false, error: "terminology 必须是数组" };

  return { ok: true, value: data as BrandFacts };
}

export async function saveBrandFacts(
  facts: BrandFacts,
  _userId?: string
): Promise<void> {
  const stamped: BrandFacts = {
    ...facts,
    _meta: {
      ...(facts._meta ?? {}),
      lastReviewed: new Date().toISOString().slice(0, 10),
    },
  };
  await backupAndWrite(BRAND_PATH, "brand-facts", stamped);
}

