import brandFacts from "@/data/brand-facts.json";
import type { PolishVariant } from "@/lib/types";

const BANNED: string[] = brandFacts.compliance?.bannedPhrases ?? [];

const SPEC_PATTERNS: RegExp[] = [
  /IP\d{2}/gi,
  /\d+[\s-]*(?:小时|个小时|hours?|hrs?)/gi,
  /\d+[\s-]*mAh/gi,
  /\d+[\s-]*(?:克|grams?)/gi,
  /\d+\s*%/g,
  /\d+[\s-]*(?:dB|分贝)/gi,
];

// 品牌事实层里出现的数字白名单:这些是品牌对外既有表述(如 5300 专利),
// 模型引用它们不算"编造"。注意不把整份事实拼进 sourceText——否则任何数字都会被
// 误判为"安全",护栏形同虚设。
const BRAND_NUMBERS: Set<string> = new Set(
  (JSON.stringify(brandFacts).match(/\d+/g) ?? []).map((n) => n.toLowerCase())
);

// 仅用"原文 + 用户背景"作为编造判定的依据。
export function buildSourceText(input: string, background?: string): string {
  return (input + " " + (background ?? "")).toLowerCase();
}

export function applyGuards(
  variant: PolishVariant,
  sourceText: string
): PolishVariant {
  const risks = variant.risks ? [...variant.risks] : [];

  const bannedHits = BANNED.filter((p) => variant.text.includes(p));
  if (bannedHits.length > 0) {
    const flag = `可能含广告法绝对化用语: ${bannedHits.join("、")}`;
    if (!risks.includes(flag)) risks.push(flag);
  }

  const fabricated = new Set<string>();
  for (const pat of SPEC_PATTERNS) {
    const matches = variant.text.match(pat);
    if (!matches) continue;
    for (const m of matches) {
      const num = m.match(/\d+/)?.[0];
      if (!num) continue;
      const n = num.toLowerCase();
      if (!sourceText.includes(n) && !BRAND_NUMBERS.has(n)) {
        fabricated.add(m.trim());
      }
    }
  }
  if (fabricated.size > 0) {
    risks.push(`可能编造的规格/数字(原文未出现): ${[...fabricated].join("、")}`);
  }

  return risks.length > 0 ? { ...variant, risks } : variant;
}

