export function applyGuards(
  variant: PolishVariant,
  sourceText: string,
  bannedPhrases: string[] = [],
  brandNumbers: Set<string> = new Set()
): PolishVariant {
  const risks = variant.risks ? [...variant.risks] : [];

  const bannedHits = bannedPhrases.filter((p) => variant.text.includes(p));
  if (bannedHits.length > 0) {
    const flag = `可能含广告法绝对化用语: ${bannedHits.join("、")}`;
    if (!risks.includes(flag)) risks.push(flag);
  }

  const fabricated = new Set<string>();
  for (const pat of SPEC_PATTERNS) {
    const matches = variant.text.match(pat);
    if (!matches) continue;
    for (const m of matches) {
      const num = m.match(/\d+/)?.[0];
      if (!num) continue;
      const n = num.toLowerCase();
      if (!sourceText.includes(n) && !brandNumbers.has(n)) {
