import { getStylePalette, saveStylePalette, validateStylePalette } from "@/lib/store";
import { checkAuth } from "@/lib/auth";

export const runtime = "nodejs";

// 公开读取:供前端风格选择器与后台编辑台取数(数据本就随页面下发,非机密)
export async function GET() {
  try {
    const palette = await getStylePalette();
    return NextResponse.json(palette, {
      headers: { "Cache-Control": "no-store" },
    });
  } catch {
    return NextResponse.json({ error: "读取风格库失败" }, { status: 500 });
  }
}

// 写回:需口令;校验通过后原子写 + 备份
export async function PUT(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const result = validateStylePalette(body);
  if (!result.ok || !result.value) {
    return NextResponse.json({ error: result.error ?? "风格库校验失败" }, { status: 400 });
  }

  try {
    await saveStylePalette(result.value);
    return NextResponse.json({ ok: true, count: result.value.length });
  } catch {
    return NextResponse.json({ error: "保存失败" }, { status: 500 });
  }
}

