"use client";

import { useEffect, useState } from "react";
import type { StyleEntry } from "@/lib/types";
import { authFetch } from "@/lib/clientAuth";

function newId(): string {
  return "style-" + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
}

export default function StyleEditor() {
  const [entries, setEntries] = useState<StyleEntry[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    fetch("/api/style-palette")
      .then((r) => (r.ok ? r.json() : []))
      .then((d) => setEntries(Array.isArray(d) ? d : []))
      .catch(() => setEntries([]))
      .finally(() => setLoaded(true));
  }, []);

  function update(idx: number, patch: Partial<StyleEntry>) {
    setEntries((prev) => prev.map((e, i) => (i === idx ? { ...e, ...patch } : e)));
  }

  function add() {
    setEntries((prev) => [
      ...prev,
      { id: newId(), name: "", essence: "", group: "未分组", isDefault: false },
    ]);
  }

  function remove(idx: number) {
    setEntries((prev) => prev.filter((_, i) => i !== idx));
  }

  async function save() {
    setSaving(true);
    setMsg("");
    try {
      const res = await authFetch("/api/style-palette", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(entries),
      });
      const data = await res.json().catch(() => ({}));
      setMsg(res.ok ? `已保存 ${data.count} 条风格` : `保存失败:${data.error || res.status}`);
    } catch {
      setMsg("保存请求失败");
    } finally {
      setSaving(false);
    }
  }

  if (!loaded) return <p className="text-sm text-ink-faint">加载中…</p>;

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={add}
          className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-sm text-ink-soft hover:border-brand"
        >
          + 新增风格
        </button>
        <button
          type="button"
          onClick={save}
          disabled={saving}
          className="rounded-lg bg-brand px-4 py-1.5 text-sm font-semibold text-white hover:bg-brand-dark disabled:opacity-60"
        >
          {saving ? "保存中…" : "保存风格库"}
        </button>
        {msg && <span className="text-sm text-ink-soft">{msg}</span>}
      </div>

      <p className="text-xs text-ink-faint">
        勾选「默认灵感」的风格,会在用户未选任何风格时作为提示注入。id 不可改(改 id 等于删旧建新)。
      </p>

      <div className="space-y-3">
        {entries.map((e, i) => (
          <div key={e.id} className="rounded-lg border border-gray-200 bg-white p-3">
            <div className="grid grid-cols-1 gap-2 md:grid-cols-3">
              <input
                value={e.name}
                onChange={(ev) => update(i, { name: ev.target.value })}
                placeholder="名称"
                className="rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none"
              />
              <input
                value={e.group}
                onChange={(ev) => update(i, { group: ev.target.value })}
                placeholder="分组"
                className="rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none"
              />
              <div className="flex items-center justify-between gap-2">
                <label className="flex items-center gap-1.5 text-sm text-ink-soft">
                  <input
                    type="checkbox"
                    checked={e.isDefault === true}
                    onChange={(ev) => update(i, { isDefault: ev.target.checked })}
                  />
                  默认灵感
                </label>
                <button
                  type="button"
                  onClick={() => remove(i)}
                  className="text-sm text-red-600 hover:underline"
                >
                  删除
                </button>
              </div>
            </div>
            <textarea
              value={e.essence}
              onChange={(ev) => update(i, { essence: ev.target.value })}
              placeholder="一句话精髓"
              rows={2}
              className="mt-2 w-full resize-none rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none"
            />
            <p className="mt-1 text-[11px] text-ink-faint">id: {e.id}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

