import { NextRequest, NextResponse } from "next/server";
import { extractBrandFacts } from "@/lib/llm";
import { getBrandFacts } from "@/lib/store";
import { checkAuth } from "@/lib/auth";

export const runtime = "nodejs";
export const maxDuration = 120;

// 上传文档的纯文本 → 模型结构化抽取(以现有事实为底覆盖文档涉及字段)→ 返回草稿,供前端表单编辑
export async function POST(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let body: { text?: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const text = (body.text ?? "").toString().trim();
  if (!text) {
    return NextResponse.json({ error: "缺少文档文本" }, { status: 400 });
  }

  try {
    const current = await getBrandFacts();
    const draft = await extractBrandFacts(text, current);
    return NextResponse.json(draft);
  } catch (err) {
    const message = err instanceof Error ? err.message : "抽取失败,请重试";
    return NextResponse.json({ error: message }, { status: 502 });
  }
}

"use client";

import { useEffect, useState } from "react";
import type { BrandFacts } from "@/lib/types";
import { authFetch } from "@/lib/clientAuth";
import FileDropzone from "@/components/FileDropzone";

const EMPTY: BrandFacts = {
  brand: "",
  positioning: {
    tagline: "",
    oneLiner: "",
    category: "",
    coreMessage: "",
    productFamilies: [],
  },
  toneCard: { voice: "", do: [], dont: [] },
  products: [],
  proofPoints: [],
  terminology: [],
  compliance: { bannedPhrases: [], healthClaimNote: "", superlativeNote: "", policy: "" },
};

const inputCls =
  "w-full rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none";

// 字符串数组编辑器
function StringList({
  items,
  onChange,
  placeholder,
}: {
  items: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
}) {
  return (
    <div className="space-y-1.5">
      {items.map((it, i) => (
        <div key={i} className="flex gap-2">
          <input
            value={it}
            placeholder={placeholder}
            onChange={(e) => onChange(items.map((x, j) => (j === i ? e.target.value : x)))}
            className={inputCls}
          />
          <button
            type="button"
            onClick={() => onChange(items.filter((_, j) => j !== i))}
            className="shrink-0 text-sm text-red-600 hover:underline"
          >
            删
          </button>
        </div>
      ))}
      <button
        type="button"
        onClick={() => onChange([...items, ""])}
        className="text-xs text-brand-dark hover:underline"
      >
        + 添加一项
      </button>
    </div>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-lg border border-gray-200 bg-white p-4">
      <h3 className="mb-2 text-sm font-semibold text-ink">{title}</h3>
      {children}
    </div>
  );
}

export default function BrandEditor() {
  const [facts, setFacts] = useState<BrandFacts | null>(null);
  const [saving, setSaving] = useState(false);
  const [extracting, setExtracting] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    fetch("/api/brand-facts")
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => setFacts(d || EMPTY))
      .catch(() => setFacts(EMPTY));
  }, []);

  function patch(p: Partial<BrandFacts>) {
    setFacts((prev) => ({ ...(prev ?? EMPTY), ...p }));
  }

  async function onDocParsed(text: string) {
    setExtracting(true);
    setMsg("正在从文档抽取…");
    try {
      const res = await authFetch("/api/brand-facts/extract", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setMsg(`抽取失败:${data.error || res.status}`);
        return;
      }
      setFacts({ ...EMPTY, ...data });
      setMsg("抽取完成,请在下方核对后保存");
    } catch {
      setMsg("抽取请求失败");
    } finally {
      setExtracting(false);
    }
  }

  async function save() {
    if (!facts) return;
    setSaving(true);
    setMsg("");
    try {
      const res = await authFetch("/api/brand-facts", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(facts),
      });
      const data = await res.json().catch(() => ({}));
      setMsg(res.ok ? "已保存品牌事实" : `保存失败:${data.error || res.status}`);
    } catch {
      setMsg("保存请求失败");
    } finally {
      setSaving(false);
    }
  }

  if (!facts) return <p className="text-sm text-ink-faint">加载中…</p>;

  const pos = facts.positioning;
  const tone = facts.toneCard;
  const comp = facts.compliance;

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        <FileDropzone variant="inline" label="上传文档抽取" onParsed={(t) => onDocParsed(t)} />
        <button
          type="button"
          onClick={() => {
            setFacts(EMPTY);
            setMsg("已清空,可从零填写");
          }}
          className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-sm text-ink-soft hover:border-brand"
        >
          新建空白
        </button>
        <button
          type="button"
          onClick={save}
          disabled={saving || extracting}
          className="rounded-lg bg-brand px-4 py-1.5 text-sm font-semibold text-white hover:bg-brand-dark disabled:opacity-60"
        >
          {saving ? "保存中…" : "保存品牌事实"}
        </button>
        {msg && <span className="text-sm text-ink-soft">{msg}</span>}
      </div>

      <Section title="品牌">
        <input
          value={facts.brand}
          onChange={(e) => patch({ brand: e.target.value })}
          placeholder="品牌名"
          className={inputCls}
        />
      </Section>

      <Section title="定位 positioning">
        <div className="grid grid-cols-1 gap-2 md:grid-cols-2">
          <input value={pos.tagline} onChange={(e) => patch({ positioning: { ...pos, tagline: e.target.value } })} placeholder="tagline" className={inputCls} />
          <input value={pos.category} onChange={(e) => patch({ positioning: { ...pos, category: e.target.value } })} placeholder="category" className={inputCls} />
        </div>
        <input value={pos.oneLiner} onChange={(e) => patch({ positioning: { ...pos, oneLiner: e.target.value } })} placeholder="oneLiner" className={`${inputCls} mt-2`} />
        <textarea value={pos.coreMessage} onChange={(e) => patch({ positioning: { ...pos, coreMessage: e.target.value } })} placeholder="coreMessage" rows={2} className={`${inputCls} mt-2 resize-none`} />
        <p className="mb-1 mt-3 text-xs text-ink-faint">产品家族 productFamilies</p>
        <StringList items={pos.productFamilies} onChange={(next) => patch({ positioning: { ...pos, productFamilies: next } })} />
      </Section>

      <Section title="腔调卡 toneCard">
        <textarea value={tone.voice} onChange={(e) => patch({ toneCard: { ...tone, voice: e.target.value } })} placeholder="voice" rows={2} className={`${inputCls} resize-none`} />
        <p className="mb-1 mt-3 text-xs text-ink-faint">宜 do</p>
        <StringList items={tone.do} onChange={(next) => patch({ toneCard: { ...tone, do: next } })} />
        <p className="mb-1 mt-3 text-xs text-ink-faint">忌 dont</p>
        <StringList items={tone.dont} onChange={(next) => patch({ toneCard: { ...tone, dont: next } })} />
      </Section>

      <Section title="产品 products">
        <div className="space-y-2">
          {facts.products.map((p, i) => (
            <div key={i} className="grid grid-cols-1 gap-2 md:grid-cols-[1fr_1fr_2fr_auto]">
              <input value={p.name} onChange={(e) => patch({ products: facts.products.map((x, j) => (j === i ? { ...x, name: e.target.value } : x)) })} placeholder="name" className={inputCls} />
              <input value={p.category} onChange={(e) => patch({ products: facts.products.map((x, j) => (j === i ? { ...x, category: e.target.value } : x)) })} placeholder="category" className={inputCls} />
              <input value={p.line} onChange={(e) => patch({ products: facts.products.map((x, j) => (j === i ? { ...x, line: e.target.value } : x)) })} placeholder="line" className={inputCls} />
              <button type="button" onClick={() => patch({ products: facts.products.filter((_, j) => j !== i) })} className="text-sm text-red-600 hover:underline">删</button>
            </div>
          ))}
          <button type="button" onClick={() => patch({ products: [...facts.products, { name: "", category: "", line: "" }] })} className="text-xs text-brand-dark hover:underline">+ 添加产品</button>
        </div>
      </Section>

      <Section title="信任背书 proofPoints">
        <StringList items={facts.proofPoints} onChange={(next) => patch({ proofPoints: next })} />
      </Section>

      <Section title="术语 terminology">
        <div className="space-y-2">
          {facts.terminology.map((t, i) => (
            <div key={i} className="grid grid-cols-1 gap-2 md:grid-cols-[1fr_1fr_2fr_auto]">
              <input value={t.term} onChange={(e) => patch({ terminology: facts.terminology.map((x, j) => (j === i ? { ...x, term: e.target.value } : x)) })} placeholder="term" className={inputCls} />
              <input value={t.preferred} onChange={(e) => patch({ terminology: facts.terminology.map((x, j) => (j === i ? { ...x, preferred: e.target.value } : x)) })} placeholder="preferred" className={inputCls} />
              <input value={t.note ?? ""} onChange={(e) => patch({ terminology: facts.terminology.map((x, j) => (j === i ? { ...x, note: e.target.value } : x)) })} placeholder="note" className={inputCls} />
              <button type="button" onClick={() => patch({ terminology: facts.terminology.filter((_, j) => j !== i) })} className="text-sm text-red-600 hover:underline">删</button>
            </div>
          ))}
          <button type="button" onClick={() => patch({ terminology: [...facts.terminology, { term: "", preferred: "", note: "" }] })} className="text-xs text-brand-dark hover:underline">+ 添加术语</button>
        </div>
      </Section>

      <Section title="合规 compliance">
        <p className="mb-1 text-xs text-ink-faint">违禁词 bannedPhrases(护栏据此标记)</p>
        <StringList items={comp.bannedPhrases} onChange={(next) => patch({ compliance: { ...comp, bannedPhrases: next } })} placeholder="违禁词" />
        <textarea value={comp.healthClaimNote ?? ""} onChange={(e) => patch({ compliance: { ...comp, healthClaimNote: e.target.value } })} placeholder="healthClaimNote" rows={2} className={`${inputCls} mt-2 resize-none`} />
        <textarea value={comp.superlativeNote ?? ""} onChange={(e) => patch({ compliance: { ...comp, superlativeNote: e.target.value } })} placeholder="superlativeNote" rows={2} className={`${inputCls} mt-2 resize-none`} />
        <textarea value={comp.policy ?? ""} onChange={(e) => patch({ compliance: { ...comp, policy: e.target.value } })} placeholder="policy" rows={2} className={`${inputCls} mt-2 resize-none`} />
      </Section>

      {facts._meta?.lastReviewed && (
        <p className="text-xs text-ink-faint">上次核对:{facts._meta.lastReviewed}(保存时自动更新)</p>
      )}
    </div>
  );
}

