import { describe, it, expect } from "vitest";
import {
  extractVariants,
  extractStreaming,
  extractDetectedLang,
} from "@/lib/parseStream";

const FULL = JSON.stringify({
  variants: [
    { text: "Stay aware while you run.", focus: "安全", intent: "强调安全", reason: "贴合骨传导卖点", risks: [] },
    { text: "听得见世界,也听得见音乐。", focus: "场景", intent: "双关", reason: "中文味", risks: [] },
  ],
  detectedSourceLang: "英语",
});

describe("extractVariants", () => {
  it("从完整 JSON 取出全部已闭合 variant", () => {
    const out = extractVariants(FULL);
    expect(out).toHaveLength(2);
    expect(out[0].text).toBe("Stay aware while you run.");
    expect(out[1].focus).toBe("场景");
  });

  it("没有 variants 字段时返回空数组", () => {
    expect(extractVariants('{"foo":1}')).toEqual([]);
  });

  it("跳过 text 为空的对象(coerceVariant 过滤)", () => {
    const buf = JSON.stringify({ variants: [{ text: "", focus: "x" }, { text: "ok", focus: "y" }] });
    const out = extractVariants(buf);
    expect(out).toHaveLength(1);
    expect(out[0].text).toBe("ok");
  });
});

describe("extractStreaming", () => {
  it("text 尚未闭合也能先返回进行中的那条", () => {
    // 第一条已闭合,第二条 text 正在生成(引号未闭合)
    const buf =
      '{"variants":[{"text":"done","focus":"A","intent":"","reason":"","risks":[]},{"text":"正在生成中的文案';
    const out = extractStreaming(buf);
    expect(out).toHaveLength(2);
    expect(out[0].text).toBe("done");
    expect(out[1].text).toBe("正在生成中的文案");
  });

  it("数组已结束时不返回半成品", () => {
    const out = extractStreaming(FULL);
    expect(out).toHaveLength(2);
  });
});

describe("extractDetectedLang", () => {
  it("解析 detectedSourceLang", () => {
    expect(extractDetectedLang(FULL)).toBe("英语");
  });
  it("缺失时返回 undefined", () => {
    expect(extractDetectedLang('{"variants":[]}')).toBeUndefined();
  });
});

